const API=(location.port==='5500'||location.port==='5501')?'http://127.0.0.1:8765':'';const $=s=>document.querySelector(s);const content=$('#content');let state={products:[],dash:null};
async function api(url,opt){const r=await fetch(url,opt);if(!r.ok){const raw=await r.text();let msg=raw;try{const parsed=JSON.parse(raw);msg=parsed.detail||parsed.message||raw}catch{}throw new Error(msg||('Request failed ('+r.status+')'))}return r.json()}
const money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:0});
function card(label,value,sub=''){return `<div class="card"><div class="label">${label}</div><div class="metric">${value}</div><div class="sub">${sub}</div></div>`}
function setHead(t,s){$('#title').textContent=t;$('#subtitle').textContent=s}
function list(items,cls=''){return `<ul class="clean-list ${cls}">${items.map(x=>`<li>${x}</li>`).join('')}</ul>`}
async function home(){setHead('Overview','Your craft, ready for its next market.');const d=await api('/api/dashboard');state.dash=d;const k=d.kpis||{};content.innerHTML=`<section class="dashboard-hero"><div class="dashboard-hero-copy"><span class="eyebrow">CRAFTED BY HAND · ROOTED IN INDIA</span><h2>Your hands make the craft.<br>We help more people find it.</h2><p>Showcase your work, understand your business and reach buyers who value handmade craft.</p><div class="dashboard-actions"><button class="btn" onclick="document.querySelector('[data-page=products]').click()">Explore your products</button><button class="btn alt" onclick="document.querySelector('[data-page=markets]').click()">Find a market</button></div></div></section><div class="grid dashboard-kpis">${card('Historical revenue',k.revenue?money(k.revenue):'—','Recorded imported sales')}${card('Transactions',k.orders||0,'Historical records')}${card('Units sold',k.units||0,'Across imported history')}${card('Markets found',k.markets||0,'Cities/markets in data')}</div><div class="dashboard-lower"><div class="card"><div class="section-title"><div><span class="eyebrow">YOUR NEXT STEPS</span><h2>Decision recommendations</h2></div><span class="pill">${d.confidence||'Medium'} confidence</span></div>${(d.recommendations||[]).map(x=>`<div class="rec"><span class="priority">${x.priority}</span><strong>${x.title}</strong><p>${x.detail}</p></div>`).join('')||'<div class="empty">Import historical data to unlock evidence-based recommendations.</div>'}</div><div class="card"><div class="section-title"><div><span class="eyebrow">FROM YOUR RECORDS</span><h2>Top products</h2></div><span class="pill">Revenue</span></div>${(d.top_products||[]).map(x=>`<div style="margin-bottom:15px"><b style="font-size:12px">${x.name}</b><div class="bar"><i style="width:${Math.min(100,(x.revenue/(d.top_products[0]?.revenue||1))*100)}%"></i></div><div class="sub">${x.units} units · ${money(x.revenue)}</div></div>`).join('')||'<div class="empty">No history yet.</div>'}</div></div>`}
async function history(){setHead('Historical Data Intelligence','Import, validate, manage, analyze and export the artisan’s existing business records.');content.innerHTML=`<div class="notice"><b>Your data stays yours.</b> Original uploads are preserved separately from standardized records. You can add new history, replace all history, review every record, export filtered data, or delete an import.</div><div id="historySummary" class="grid" style="margin-top:16px"></div><div class="two" style="margin-top:16px"><div class="card"><div class="section-title"><h2>1. Import historical data</h2><span class="pill">CSV / Excel</span></div><div class="drop"><b>Choose your old sales file</b><br><span class="sub">CSV, XLSX or XLS. Nothing is saved until you confirm the import.</span><br><input id="file" type="file" accept=".csv,.xlsx,.xls"><br><div class="form" style="margin-top:12px"><div class="field"><label>Import mode</label><select id="importMode"><option value="add">Add to existing data</option><option value="replace">Replace all existing history</option></select></div></div><button class="btn" style="margin-top:12px" onclick="previewImport()">Analyze File</button></div><div id="importResult" style="margin-top:14px"></div></div><div class="card"><div class="section-title"><h2>What happens before import?</h2></div><div class="rec"><strong>① Detect columns</strong><p>Maps common names such as Qty, Units, Sale Date, Customer and Amount.</p></div><div class="rec"><strong>② Check quality</strong><p>Finds missing products/prices/dates and duplicate rows before saving.</p></div><div class="rec"><strong>③ Confirm</strong><p>You choose the import mode and can adjust the detected column mapping.</p></div><div class="rec"><strong>④ Analyze</strong><p>Imported records immediately become available to Historical Intelligence, Market Intelligence and Impact Dashboard.</p></div></div></div><div class="card" style="margin-top:16px"><div class="section-title"><h2>Historical Records</h2><div class="actions"><button class="btn alt" onclick="exportHistory()">Export CSV</button><button class="btn alt" onclick="deleteAllHistory()">Delete All</button><button class="btn alt" onclick="history()">Refresh</button></div></div><div class="form" style="margin-bottom:12px"><div class="field"><label>Search product, buyer or city</label><input id="historySearch" placeholder="e.g. Bamboo, Indore, retailer" onkeydown="if(event.key==='Enter')loadHistoryRecords(0)"></div><div class="field"><label>Dataset</label><select id="historyDataset" onchange="loadHistoryRecords(0)"><option value="0">All imports</option></select></div></div><div id="records">Loading records…</div></div><div class="card" style="margin-top:16px"><div class="section-title"><h2>Import History</h2><span class="pill">Data lineage</span></div><div id="datasets">Loading...</div></div>`;loadHistoryPage()}
async function previewImport(){const f=$('#file').files[0];if(!f)return alert('Choose a CSV or Excel file first.');const fd=new FormData();fd.append('file',f);fd.append('artisan_id','1');$('#importResult').innerHTML='<div class="notice">Analyzing columns, duplicates and data quality…</div>';try{const r=await api('/api/import/preview',{method:'POST',body:fd});window.importPreview={file:f,headers:r.headers,mapping:r.mapping,report:r.report};renderImportPreview(r)}catch(e){$('#importResult').innerHTML='<div class="notice error">'+e.message+'</div>'}}
function renderImportPreview(r){const fields=['date','product','quantity','price','buyer','city','payment'];const labels={date:'Sale date',product:'Product',quantity:'Quantity',price:'Price',buyer:'Buyer / Customer',city:'City / Market',payment:'Payment'};const opts=['<option value="">Not mapped</option>'].concat(r.headers.map(h=>`<option value="${escapeHtml(h)}">${escapeHtml(h)}</option>`)).join('');const maps=fields.map(k=>`<div class="field"><label>${labels[k]}</label><select id="map_${k}">${opts}</select></div>`).join('');setTimeout(()=>fields.forEach(k=>{const el=$('#map_'+k);if(el&&r.mapping[k])el.value=r.mapping[k]}),0);$('#importResult').innerHTML=`<div class="notice ${r.report.quality<70?'error':'success'}"><b>Preview — nothing saved yet.</b><br>${r.report.rows} rows detected · ${r.report.valid_rows} look valid · Quality ${r.report.quality}/100 · ${r.report.duplicates} duplicate rows · ${r.report.missing_product} missing products · ${r.report.missing_price} missing prices · ${r.report.missing_date} missing dates.${r.report.issues.length?'<br><b>Issues:</b> '+r.report.issues.join(' · '):''}</div><div class="card" style="margin-top:12px"><div class="section-title"><h3>Column Mapping</h3><span class="pill">Adjust if needed</span></div><div class="form">${maps}</div><div class="actions" style="margin-top:12px"><button class="btn" onclick="confirmImport()">Confirm & Import</button><button class="btn alt" onclick="$('#importResult').innerHTML=''">Cancel</button></div></div>`}
async function confirmImport(){const p=window.importPreview;if(!p)return;const mapping={};['date','product','quantity','price','buyer','city','payment'].forEach(k=>{const v=$('#map_'+k)?.value;if(v)mapping[k]=v});if(!mapping.product)return alert('Map the Product column before importing.');if(!mapping.price)if(!confirm('No Price column is mapped. Continue?'))return;const mode=$('#importMode').value;if(mode==='replace'&&!confirm('Replace mode will permanently remove all existing historical imports before adding this file. Continue?'))return;const fd=new FormData();fd.append('file',p.file);fd.append('artisan_id','1');fd.append('import_mode',mode);fd.append('mapping_json',JSON.stringify(mapping));$('#importResult').innerHTML='<div class="notice">Importing and rebuilding historical intelligence…</div>';try{const r=await api('/api/import/csv',{method:'POST',body:fd});$('#importResult').innerHTML=`<div class="notice success"><b>Import complete.</b><br>${r.imported_rows} records saved · ${r.skipped_rows||0} skipped · Quality ${r.quality}/100 · Mode: ${r.mode==='replace'?'Replace':'Add'}.<br><span class="sub">Your Historical Records table below now includes the imported data.</span></div>`;window.importPreview=null;loadHistoryPage()}catch(e){$('#importResult').innerHTML='<div class="notice error">'+e.message+'</div>'}}
async function loadHistoryPage(){await Promise.all([loadHistorySummary(),loadDatasets(),loadHistoryRecords(0)])}
async function loadHistorySummary(){const r=await api('/api/historical/summary');$('#historySummary').innerHTML=card('Historical records',r.records,'All stored transactions')+card('Imported datasets',r.datasets,'Original uploads')+card('Revenue',money(r.revenue),'Recorded historical sales')+card('Units',r.units,'Recorded quantity')+card('Products',r.products,'Distinct products')+card('Markets',r.markets,'Distinct recorded cities/markets')}
async function loadHistoryRecords(offset=0){const search=encodeURIComponent($('#historySearch')?.value||'');const did=$('#historyDataset')?.value||0;const r=await api(`/api/historical/records?search=${search}&dataset_id=${did}&limit=25&offset=${offset}`);const pages=Math.max(1,Math.ceil(r.total/r.limit));const page=Math.floor(r.offset/r.limit)+1;$('#records').innerHTML=r.total?`<div class="sub" style="margin-bottom:8px">Showing ${r.offset+1}–${Math.min(r.offset+r.rows.length,r.total)} of ${r.total} records</div><div style="overflow:auto"><table class="table"><tr><th>Date</th><th>Product</th><th>Qty</th><th>Price</th><th>Buyer</th><th>City</th><th>Dataset</th><th></th></tr>${r.rows.map(x=>`<tr><td>${escapeHtml(x.sale_date||'—')}</td><td><b>${escapeHtml(x.product)}</b></td><td>${x.quantity}</td><td>${money(x.price)}</td><td>${escapeHtml(x.buyer||'—')}</td><td>${escapeHtml(x.city||'—')}</td><td><span class="sub">${escapeHtml(x.dataset_name)}</span></td><td><button class="btn alt" onclick="deleteRecord(${x.id})">Delete</button></td></tr>`).join('')}</table></div><div class="actions" style="margin-top:12px">${page>1?`<button class="btn alt" onclick="loadHistoryRecords(${(page-2)*r.limit})">Previous</button>`:''}<span class="pill">Page ${page} / ${pages}</span>${page<pages?`<button class="btn alt" onclick="loadHistoryRecords(${page*r.limit})">Next</button>`:''}</div>`:'<div class="empty">No historical records match your filters.</div>'}
async function loadDatasets(){const r=await api('/api/datasets');const sel=$('#historyDataset');if(sel){const current=sel.value;sel.innerHTML='<option value="0">All imports</option>'+r.map(x=>`<option value="${x.id}">${escapeHtml(x.name)} · ${x.rows} rows</option>`).join('');if([...sel.options].some(o=>o.value===current))sel.value=current}$('#datasets').innerHTML=r.length?`<table class="table"><tr><th>File</th><th>Rows</th><th>Quality</th><th>Imported</th><th>Mapping</th><th>Actions</th></tr>${r.map(x=>`<tr><td><b>${escapeHtml(x.name)}</b></td><td>${x.rows}</td><td>${x.quality}/100</td><td>${new Date(x.imported_at).toLocaleString()}</td><td>${Object.keys(JSON.parse(x.mapping_json||'{}')).length} fields</td><td><button class="btn alt" onclick="exportDataset(${x.id})">Export</button> <button class="btn alt" onclick="deleteDataset(${x.id},'${escapeHtml(x.name)}')">Delete</button></td></tr>`).join('')}</table>`:'<div class="empty">No historical files imported yet.</div>'}
async function deleteDataset(id,name){if(!confirm(`Delete the import "${name}" and all records from it?`))return;try{await api('/api/datasets/'+id,{method:'DELETE'});loadHistoryPage()}catch(e){alert(e.message)}}
async function deleteRecord(id){if(!confirm('Delete this historical record?'))return;try{await api('/api/historical/records/'+id,{method:'DELETE'});loadHistoryPage()}catch(e){alert(e.message)}}
async function deleteAllHistory(){if(!confirm('Delete ALL historical datasets and records? This cannot be undone.'))return;try{const result=await api('/api/historical/all',{method:'DELETE'});if($('#historySearch'))$('#historySearch').value='';if($('#historyDataset'))$('#historyDataset').value='0';await loadHistoryPage();alert(`Historical data cleared: ${result.deleted_datasets||0} imports and ${result.deleted_records||0} records deleted. Products and account details were kept.`)}catch(e){alert(e.message)}}
function exportHistory(){const search=encodeURIComponent($('#historySearch')?.value||'');const did=$('#historyDataset')?.value||0;window.open(`${API}/api/historical/export?search=${search}&dataset_id=${did}`,'_blank')}
function exportDataset(id){window.open(`${API}/api/historical/export?dataset_id=${id}`,'_blank')}
async function products(){
 setHead('Products','Build and manage the digital product identities used by Catalogue, Pricing and Market Intelligence.');
 state.products=await api('/api/products');
 content.innerHTML=`<div class="grid">${card('Products',state.products.length,'Digital craft identities')}${card('With pricing',state.products.filter(p=>Number(p.price)>0).length,'Products with a list price')}${card('With capacity',state.products.filter(p=>Number(p.capacity_week)>0).length,'Products with weekly capacity')}${card('Ready for matching',state.products.filter(p=>p.name&&p.material&&p.price).length,'Enough information for decision support')}</div>
 <div class="two" style="margin-top:16px"><div class="card"><div class="section-title"><h2>Product registry</h2><span class="pill">${state.products.length} products</span></div>${state.products.length?`<div style="overflow:auto"><table class="table"><tr><th>Product</th><th>Price</th><th>Cost</th><th>Margin</th><th>Capacity/wk</th><th></th></tr>${state.products.map(p=>{const margin=p.price?Math.round((p.price-p.cost)/p.price*100):0;return `<tr><td><b>${escapeHtml(p.name)}</b><br><span class="sub">${escapeHtml(p.material||'—')} · ${escapeHtml(p.craft||'—')} · ${escapeHtml(p.region||'—')}</span></td><td>${money(p.price)}</td><td>${money(p.cost)}</td><td>${margin}%</td><td>${p.capacity_week||0}</td><td><button class="btn alt" onclick="selectProduct(${p.id})">Open</button></td></tr>`}).join('')}</table></div>`:'<div class="empty">No products yet. Create your first digital craft identity on the right.</div>'}</div>
 <div class="card"><div class="section-title"><h2>Create product</h2><span class="pill">Step 1</span></div><div class="form"><div class="field"><label>Name *</label><input id="pn" placeholder="e.g. Bamboo Storage Basket"></div><div class="field"><label>Craft</label><input id="pc" value="Bamboo Craft"></div><div class="field"><label>Material</label><input id="pm" value="Bamboo"></div><div class="field"><label>Region</label><input id="pr" value="Madhya Pradesh"></div><div class="field"><label>Technique</label><input id="pt" value="Handwoven"></div><div class="field"><label>Cost ₹</label><input id="pco" type="number" min="0" value="300"></div><div class="field"><label>List price ₹</label><input id="pp" type="number" min="0" value="499"></div><div class="field"><label>Weekly capacity</label><input id="cap" type="number" min="0" value="20"></div><div class="field full"><label>Description</label><textarea id="pd" rows="4" placeholder="What is it used for? What makes it special?"></textarea></div></div><button class="btn primary" style="margin-top:12px" onclick="addProduct()">Create product identity</button><div id="productMsg" style="margin-top:12px"></div></div></div><div id="productOpen" style="margin-top:16px"></div>`;
}
async function addProduct(){
 const name=$('#pn').value.trim(); if(!name){alert('Enter a product name.');return}
 const payload={artisan_id:1,name,craft:$('#pc').value.trim(),material:$('#pm').value.trim(),region:$('#pr').value.trim(),technique:$('#pt').value.trim(),cost:+$('#pco').value||0,price:+$('#pp').value||0,capacity_week:+$('#cap').value||0,description:$('#pd').value.trim()};
 try{const r=await api('/api/products',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('#productMsg').innerHTML=`<div class="notice success">Product created successfully. Product ID: ${r.id}</div>`;await products();setTimeout(()=>selectProduct(r.id),50)}catch(e){$('#productMsg').innerHTML=`<div class="notice error">${escapeHtml(e.message)}</div>`}
}
async function selectProduct(id){
 try{
  const p=state.products.find(x=>x.id===id)||await api('/api/products/'+id);const [cat,price,matches]=await Promise.all([api('/api/catalogue/'+id),api('/api/pricing/'+id),api('/api/products/'+id+'/matches')]);
  const m=matches.markets||[]; const buyers=matches.top_buyers||matches.buyers||[];
  $('#productOpen').innerHTML=`<div class="card"><div class="section-title"><h2>${escapeHtml(p.name)}</h2><span class="pill">Digital identity ready</span></div><div class="grid"><div class="card"><div class="label">List price</div><div class="metric">${money(p.price)}</div><div class="sub">Cost ${money(p.cost)} · ${p.price?Math.round((p.price-p.cost)/p.price*100):0}% gross margin</div></div><div class="card"><div class="label">Recommended retail</div><div class="metric">${money(price.recommended_retail)}</div><div class="sub">Sustainable floor ${money(price.minimum_sustainable_price)}</div></div><div class="card"><div class="label">B2B starting price</div><div class="metric">${money(price.recommended_b2b)}</div><div class="sub">Based on cost, history and buyer economics</div></div><div class="card"><div class="label">Opportunity</div><div class="metric">${matches.opportunity_score||0}/100</div><div class="sub">Market & buyer fit</div></div></div><div class="two" style="margin-top:16px"><div><h3>Catalogue identity</h3><p><b>${escapeHtml(cat.title||p.name)}</b></p><p class="sub">${escapeHtml(cat.short_description||p.description||'No description yet.')}</p><div class="chips">${(cat.tags||[]).filter(Boolean).map(t=>`<span class="chip">#${escapeHtml(t)}</span>`).join('')}</div></div><div><h3>Pricing guidance</h3>${(price.guidance||[]).map(x=>`<div class="rec"><p>${escapeHtml(x)}</p></div>`).join('')}</div></div><div class="two" style="margin-top:16px"><div><h3>Top market matches</h3>${m.slice(0,3).map(x=>`<div class="rec"><strong>${escapeHtml(x.market)} · ${x.score}%</strong><p>${escapeHtml(x.demand||'')} · ${escapeHtml(x.price_fit||'')} · ${escapeHtml(x.competition||'')}</p></div>`).join('')||'<div class="empty">No market matches yet.</div>'}</div><div><h3>Top buyer matches</h3>${buyers.slice(0,3).map(x=>`<div class="rec"><strong>${escapeHtml(x.buyer)} · ${x.score||x.fit}%</strong><p>${escapeHtml((x.reasons||[]).join(' · '))}</p></div>`).join('')||'<div class="empty">No buyer profiles yet.</div>'}</div></div></div>`;
  $('#productOpen').scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){$('#productOpen').innerHTML=`<div class="notice error">Could not open this product: ${escapeHtml(e.message)}</div>`}
}
async function pricing(){
 setHead('Pricing Intelligence','Understand what the product costs, what it has historically sold for, what margin you can protect, and what price to offer different buyer types.');
 state.products=await api('/api/products');
 if(!state.products.length){content.innerHTML=`<div class="card"><div class="empty"><h2>No products yet</h2><p>Create a product first. Pricing Intelligence will then calculate sustainable, retail and B2B price guidance.</p><button class="btn primary" onclick="document.querySelector('[data-page=products]').click()">Go to Products</button></div></div>`;return}
 content.innerHTML=`<div class="notice"><b>Pricing is decision support, not a guaranteed market price.</b> Karigar Link combines product cost, list price, recorded historical selling prices when available, target margins and buyer budget fit.</div><div class="grid" style="margin-top:16px">${state.products.slice(0,6).map(p=>`<div class="card" onclick="pricingDetail(${p.id})" style="cursor:pointer"><div class="label">${escapeHtml(p.name)}</div><div class="metric">${money(p.price)}</div><div class="sub">Cost ${money(p.cost)} · ${p.price?Math.round((p.price-p.cost)/p.price*100):0}% current margin</div><div class="bar"><i style="width:${Math.min(100,Math.max(5,p.price?((p.price-p.cost)/p.price*100):5))}%"></i></div><button class="btn alt" style="margin-top:10px" onclick="event.stopPropagation();pricingDetail(${p.id})">View intelligence</button></div>`).join('')}</div><div id="priceDetail" style="margin-top:16px"></div>`;
 await pricingDetail(state.products[0].id);
}
async function pricingDetail(id){
 const r=await api('/api/pricing/'+id);const hist=r.historical||{};const buyer=r.buyer_fit||[];
 $('#priceDetail').innerHTML=`<div class="card"><div class="section-title"><h2>${escapeHtml(r.product)} — Pricing Intelligence</h2><span class="pill">Decision support</span></div><div class="grid"><div class="card"><div class="label">Minimum sustainable</div><div class="metric">${money(r.minimum_sustainable_price)}</div><div class="sub">Floor to protect basic margin</div></div><div class="card"><div class="label">30% margin</div><div class="metric">${money(r.margin_prices['30%'])}</div><div class="sub">Target gross margin</div></div><div class="card"><div class="label">40% margin</div><div class="metric">${money(r.margin_prices['40%'])}</div><div class="sub">Target gross margin</div></div><div class="card"><div class="label">50% margin</div><div class="metric">${money(r.margin_prices['50%'])}</div><div class="sub">Higher-margin scenario</div></div></div><div class="two" style="margin-top:16px"><div class="card"><h3>Recommended price ladder</h3><table class="table"><tr><th>Price</th><th>Amount</th><th>Use</th></tr><tr><td>Historical / list</td><td>${money(r.historical_or_list_price)}</td><td>Reference</td></tr><tr><td>Minimum sustainable</td><td>${money(r.minimum_sustainable_price)}</td><td>Do not undercut casually</td></tr><tr><td>Retail</td><td>${money(r.recommended_retail)}</td><td>Consumer / boutique</td></tr><tr><td>B2B</td><td>${money(r.recommended_b2b)}</td><td>Bulk conversation</td></tr></table></div><div class="card"><h3>Historical evidence</h3>${hist.transactions?`<div class="grid">${card('Transactions',hist.transactions)}${card('Units',hist.units)}${card('Revenue',money(hist.revenue))}${card('Avg realized',money(hist.average_realized_price))}</div><p class="sub">Recorded price range: ${money(hist.lowest_price)} – ${money(hist.highest_price)} · Latest recorded price: ${money(hist.latest_price)}</p>`:'<div class="empty">No matching historical sales yet. This product is currently using cost/list-price logic. Import history with the same product name to unlock realized-price evidence.</div>'}</div></div><div class="two" style="margin-top:16px"><div class="card"><h3>Buyer budget fit</h3>${buyer.map(b=>`<div class="rec"><strong>${escapeHtml(b.buyer)} · ${b.fit}%</strong><p>${escapeHtml(b.type)} · ${escapeHtml(b.city)} · Budget ${money(b.budget_min)}–${money(b.budget_max)}</p></div>`).join('')||'<div class="empty">Add buyer profiles to compare B2B price fit.</div>'}</div><div class="card"><h3>What should I do?</h3>${(r.guidance||[]).map(x=>`<div class="rec"><p>${escapeHtml(x)}</p></div>`).join('')}</div></div><div class="notice" style="margin-top:16px">${escapeHtml(r.explanation)}</div></div>`;
}
async function markets(productId=''){setHead('Market Intelligence','One place to decide where to sell, who to contact, what to offer, how much to prepare and what to do next.');state.products=await api('/api/products');content.innerHTML=`<div class="card"><div class="section-title"><h2>Choose a product</h2><span class="pill">Explainable opportunity engine</span></div><div class="chips">${state.products.map(p=>`<button class="btn alt" onclick="marketDetail(${p.id})">${escapeHtml(p.name)}</button>`).join('')}</div></div><div id="marketDetail" style="margin-top:16px"><div class="empty">Select a product to see its market and buyer opportunity.</div></div>`; if(productId) await marketDetail(productId)}
async function marketDetail(id){const p=state.products.find(x=>x.id===id),r=await api('/api/products/'+id+'/market-intelligence');const top=r.markets?.[0]||{};const rb=r.recommended_action||{};$('#marketDetail').innerHTML=`
<div class="grid market-kpis">${card('Opportunity score',`${r.opportunity_score}/100`,'Overall product opportunity')}${card('Best market',top.market||'—',`${top.score||0}% match`)}${card('Top buyer',r.top_buyers?.[0]?.buyer||'—',`${r.top_buyers?.[0]?.score||0}% match`)}${card('Historical sales',money(r.historical?.revenue||0),`${r.historical?.transactions||0} matching transactions`)}</div>
<div class="market-grid">
<div class="card"><div class="section-title"><h2>🎯 Best Markets</h2><span class="pill">Where should I sell?</span></div>${(r.markets||[]).map((x,i)=>`<div class="opportunity-row"><div class="opportunity-head"><div><b>${i+1}. ${escapeHtml(x.market)}</b><span>${escapeHtml(x.channels)}</span></div><strong>${x.score}%</strong></div><div class="bar"><i style="width:${x.score}%"></i></div><div class="tag-row"><span class="tag">Demand: ${x.demand}</span><span class="tag">Competition: ${x.competition}</span><span class="tag">Price fit: ${x.price_fit}</span><span class="tag">Season: ${x.seasonality}</span></div><p class="sub">${x.reasons.join(' · ')}</p></div>`).join('')}</div>
<div class="card"><div class="section-title"><h2>🤝 Top Buyer Matches</h2><span class="pill">Who should I contact?</span></div>${(r.top_buyers||[]).map((x,i)=>`<div class="buyer-row"><div><div class="opportunity-head"><div><b>${i+1}. ${escapeHtml(x.buyer)}</b><span>${escapeHtml(x.type)} · ${escapeHtml(x.city)}</span></div><strong>${x.score}%</strong></div><div class="tag-row"><span class="tag">Budget ₹${Number(x.budget_min).toLocaleString('en-IN')}–₹${Number(x.budget_max).toLocaleString('en-IN')}</span><span class="tag">Order ${x.volume_min}–${x.volume_max}</span><span class="tag">Price ${x.price_fit?'✓':'⚠'}</span><span class="tag">Capacity ${x.quantity_fit?'✓':'⚠'}</span></div><p class="sub">${x.reasons.join(' · ')}</p></div><button class="btn alt" onclick="openBuyerEnquiry(${id},'${escapeHtml(x.buyer).replace(/'/g,"\\'")}','${escapeHtml(x.type).replace(/'/g,"\\'")}','${escapeHtml(x.city).replace(/'/g,"\\'")}',${x.expected_order},${x.budget_max})">Enquire</button></div>`).join('')||'<div class="empty">No buyer profiles available.</div>'}</div>
<div class="card"><div class="section-title"><h2>📦 Capacity & Order Fit</h2><span class="pill">Can I fulfil it?</span></div><div class="fit-grid"><div><span>Artisan capacity</span><b>${p.capacity_week||0} units/week</b></div><div><span>Top buyer requirement</span><b>${r.top_buyers?.[0]?.volume_min||0}–${r.top_buyers?.[0]?.volume_max||0} units</b></div><div><span>Capacity fit</span><b>${r.top_buyers?.[0]?.quantity_fit?'✓ Compatible':'⚠ Review'}</b></div><div><span>Suggested first batch</span><b>${rb.quantity||0} units</b></div></div><p class="sub">If the buyer requirement exceeds current capacity, negotiate phased delivery instead of rejecting the opportunity.</p></div>
<div class="card"><div class="section-title"><h2>📍 Geographic Opportunity</h2><span class="pill">Where is demand?</span></div>${(r.top_buyers||[]).slice(0,5).map(x=>`<div class="geo-row"><b>${escapeHtml(x.city)}</b><span>${escapeHtml(x.buyer)}</span><strong>${x.location_fit}% fit</strong></div>`).join('')||'<div class="empty">Buyer location data is not available.</div>'}</div>
<div class="card"><div class="section-title"><h2>📅 Seasonal Opportunity</h2><span class="pill">When should I prepare?</span></div>${r.seasonality?.length?r.seasonality.map(x=>`<div class="geo-row"><b>Month ${x.month}</b><span>Recorded revenue</span><strong>${money(x.revenue)}</strong></div>`).join(''):`<div class="notice">No product-specific historical sales yet. The current market season is ${top.seasonality||'year-round'} based on the rule engine.</div>`}</div>
<div class="card"><div class="section-title"><h2>⭐ Recommended Action</h2><span class="pill">What should I do next?</span></div><div class="action-hero"><div><span class="label">Target market</span><b>${escapeHtml(rb.market||'—')}</b></div><div><span class="label">First buyer</span><b>${escapeHtml(rb.buyer||'—')}</b></div><div><span class="label">Offer price</span><b>${money(rb.offer_price||0)}</b></div><div><span class="label">Initial quantity</span><b>${rb.quantity||0} units</b></div><div><span class="label">Best season</span><b>${escapeHtml(rb.season||'—')}</b></div></div><div class="rec-list">${(r.actions||[]).map((x,i)=>`<div><strong>${i+1}</strong><span>${escapeHtml(x)}</span></div>`).join('')}</div></div>
<div class="card"><div class="section-title"><h2>🔄 Opportunity Pipeline</h2><span class="pill">Track the linkage</span></div><div class="pipeline"><span>Matched</span><i>→</i><span>Contacted</span><i>→</i><span>Response</span><i>→</i><span>Negotiating</span><i>→</i><span>Order</span><i>→</i><span>Completed</span></div><p class="sub">Use Buyer Enquiries to record real opportunities and move them through the business process.</p></div>
<div class="card"><div class="section-title"><h2>🧪 What-If Simulator</h2><span class="pill">Test before acting</span></div><div class="sim-grid"><label class="field"><span>Try price ₹</span><input id="simPrice" type="number" value="${p.price||0}"></label><label class="field"><span>Try capacity/week</span><input id="simCapacity" type="number" value="${p.capacity_week||0}"></label><button class="btn primary sim-btn" onclick="runMarketSimulator(${id})">Simulate</button></div><div id="simResult" class="notice" style="margin-top:12px">Change price or capacity and see how buyer fit may change.</div></div>
<div class="card"><div class="section-title"><h2>🧠 Learning From Results</h2><span class="pill">Recommendation → Outcome</span></div><div class="learning-flow"><span>Recommendation</span><i>→</i><span>Artisan Action</span><i>→</i><span>Buyer Response</span><i>→</i><span>Order</span><i>→</i><span>Revenue</span><i>→</i><span>Better Future Match</span></div><p class="sub">${escapeHtml(r.note||'Record enquiries and outcomes to validate recommendations over time.')}</p></div>
</div>`}
async function runMarketSimulator(id){const price=Number($('#simPrice').value||0),capacity=Number($('#simCapacity').value||0);const r=await api(`/api/products/${id}/market-simulator?price=${encodeURIComponent(price)}&capacity=${encodeURIComponent(capacity)}`);$('#simResult').innerHTML=`<b>Simulation result</b><br>Top buyer score: <strong>${r.top_buyer_score}%</strong> · Average buyer score: <strong>${r.average_buyer_score}%</strong><br><span class="sub">${escapeHtml(r.note)}</span>`}
function openBuyerEnquiry(id,name,type,city,quantity,budget){content.insertAdjacentHTML('beforeend',`<div id="quickEnquiry" class="modal-backdrop"><div class="card quick-modal"><div class="section-title"><h2>Send Buyer Enquiry</h2><button class="btn alt" onclick="$('#quickEnquiry').remove()">Close</button></div><form onsubmit="submitQuickEnquiry(event)"><input type="hidden" name="product_id" value="${id}"><input type="hidden" name="buyer_name" value="${name}"><input type="hidden" name="buyer_type" value="${type}"><input type="hidden" name="city" value="${city}"><input type="hidden" name="quantity" value="${quantity}"><input type="hidden" name="budget" value="${budget}"><div class="notice">Prepared for <b>${name}</b> · ${type} · ${city}</div><label class="field"><span>Message</span><textarea name="message" rows="5">Namaste, we are interested in discussing ${quantity} units of our artisan-made product. Our indicative B2B budget is ₹${Number(budget||0).toLocaleString('en-IN')}. We can discuss custom quantities and delivery.</textarea></label><button class="btn primary full">Record Enquiry</button></form></div></div>`)}
async function submitQuickEnquiry(e){e.preventDefault();const r=await api('/api/enquiries',{method:'POST',body:new FormData(e.target)});alert(r.message);$('#quickEnquiry').remove()}
async function catalogue(productId=''){setHead('Smart Catalogue','Turn one product identity into a complete market-ready catalogue, sales pitch and multilingual content pack.');state.products=await api('/api/products');content.innerHTML=`<div class="card"><div class="section-title"><h2>Catalogue generator</h2><span class="pill">Detailed market-ready output</span></div><p class="sub">Select a product. Karigar Link builds product identity, story, pricing context, customer segments, channels, SEO copy and ready-to-use marketing messages.</p><div class="chips">${state.products.map(p=>`<button class="btn alt" onclick="catDetail(${p.id})">${p.name}</button>`).join('')}</div></div><div id="catDetail" style="margin-top:16px"></div>`; if(productId) await catDetail(productId)}
function section(title,body,extra=''){return `<div class="card catalogue-section"><div class="section-title"><h2>${title}</h2>${extra}</div>${body}</div>`}
async function catDetail(id){const r=await api('/api/catalogue/'+id);$('#catDetail').innerHTML=`<div class="catalogue-grid">
${section('1. Product Identity',`<div class="identity-grid">${Object.entries(r.identity).map(([k,v])=>`<div><span class="label">${k.replaceAll('_',' ')}</span><b>${v===true?'Yes':v}</b></div>`).join('')}</div>`)}
${section('2. Marketplace Listing',`<div class="copy-block"><span class="label">Marketplace title</span><h2>${r.title}</h2><span class="label">Short description</span><p>${r.short_description}</p><span class="label">Detailed description</span><p>${r.long_description}</p></div>`)}
${section('3. Craft Story & Value Proposition',`<p class="story">${r.story}</p>${list(r.selling_points)}`)}
${section('4. Commercial Information',`<div class="grid mini-grid">${card('List price',money(r.commercial.list_price),'Current product price')}${card('Estimated cost',money(r.commercial.estimated_cost),'Recorded product cost')}${card('Gross margin',r.commercial.gross_margin_percent+'%','At current list price')}${card('Weekly capacity',r.commercial.production_capacity_week||r.identity.production_capacity_week,'Indicative production capacity')}</div><div class="two compact"><div><span class="label">Minimum order</span><b>${r.commercial.minimum_order_quantity} units</b></div><div><span class="label">Customization</span><b>${r.commercial.customization_available?'Available':'Not specified'}</b></div><div><span class="label">Packaging</span><p>${r.commercial.packaging}</p></div><div><span class="label">Shipping</span><p>${r.commercial.shipping}</p></div></div>`)}
${section('5. Who Should Buy This?',`<div class="segment-grid">${[r.market_positioning.primary_customer,...r.market_positioning.secondary_segments].map((x,i)=>`<div class="segment"><span>${i===0?'Primary':'Secondary'}</span><b>${x}</b></div>`).join('')}</div><p class="sub">Positioning: ${r.market_positioning.positioning}</p>`)}
${section('6. Where Should It Be Sold?',`<div class="channel-grid">${r.market_positioning.recommended_channels.map((x,i)=>`<div class="channel"><b>${i+1}</b><span>${x}</span></div>`).join('')}</div><span class="label">Best use cases</span><div class="chips">${r.market_positioning.use_cases.map(x=>`<span class="chip">${x}</span>`).join('')}</div>`)}
${section('7. SEO & Discovery',`<div class="chips">${r.seo_keywords.map(x=>`<span class="chip">${x}</span>`).join('')}</div>`)}
${section('8. Ready-to-Use Marketing Kit',`<div class="copy-tabs"><div><span class="label">WhatsApp selling message</span><p class="copy-card">${r.marketing.whatsapp}</p></div><div><span class="label">Instagram caption</span><p class="copy-card">${r.marketing.instagram}</p></div><div><span class="label">B2B / buyer pitch</span><p class="copy-card">${r.marketing.buyer_pitch}</p></div><div><span class="label">Call to action</span><p class="copy-card">${r.marketing.call_to_action}</p></div></div>`)}
${section('9. Hindi Catalogue',`<p class="hindi" lang="hi">${r.hindi}</p>`)}
</div>`}
function metricRow(label,value,max){const pct=max?Math.max(4,Math.min(100,value/max*100)):4;return `<div class="rank-row"><div class="rank-head"><span>${label}</span><b>${money(value)}</b></div><div class="bar"><i style="width:${pct}%"></i></div></div>`}
async function impact(){
 setHead('Business Insights & Impact','A clear view of recorded business activity, market reach, product performance and change over time.');
 const r=await api('/api/impact');
 const growth=r.growth_percent===null?'—':(r.growth_percent>=0?'+':'')+r.growth_percent+'%';
 const q=r.avg_data_quality===null?'—':r.avg_data_quality+'/100';
 const months=r.monthly_sales||[];
 const maxRev=Math.max(...months.map(x=>Number(x.revenue)||0),1);
 const maxProd=Math.max(...(r.top_products||[]).map(x=>Number(x.revenue)||0),1);
 const maxMarket=Math.max(...(r.top_markets||[]).map(x=>Number(x.revenue)||0),1);
 const maxBuyer=Math.max(...(r.top_buyers||[]).map(x=>Number(x.revenue)||0),1);
 const svgLine=()=>{
   if(!months.length) return '<div class="empty">No dated sales records are available yet. Import historical sales to build this trend.</div>';
   const w=760,h=260,pad=34;
   const pts=months.map((x,i)=>{const px=pad+(months.length===1?0:i*(w-pad*2)/(months.length-1));const py=h-pad-(Number(x.revenue)||0)/maxRev*(h-pad*2);return {x:px,y:py,label:x.month,value:Number(x.revenue)||0}});
   const path=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' ');
   const dots=pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" class="impact-dot"><title>${escapeHtml(p.label)} · ${money(p.value)}</title></circle>`).join('');
   const labels=pts.map(p=>`<text x="${p.x}" y="${h-8}" text-anchor="middle" class="impact-axis">${escapeHtml(p.label)}</text>`).join('');
   const grid=[0,.25,.5,.75,1].map(v=>{const y=h-pad-v*(h-pad*2);return `<line x1="${pad}" y1="${y}" x2="${w-pad}" y2="${y}" class="impact-gridline"/>`}).join('');
   return `<div class="impact-chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Recorded revenue trend">${grid}<path d="${path}" class="impact-line" fill="none"/>${dots}${labels}</svg></div>`;
 };
 const bars=(items,max)=>items.length?`<div class="impact-bars">${items.map(x=>`<div class="impact-bar-row"><div class="impact-bar-head"><span>${escapeHtml(x.name)}</span><b>${money(x.revenue)}</b></div><div class="impact-track"><i style="width:${Math.max(3,Math.min(100,(Number(x.revenue)||0)/max*100))}%"></i></div></div>`).join('')}</div>`:'<div class="empty">No recorded data yet.</div>';
 content.innerHTML=`
 <div class="impact-hero"><div><span class="eyebrow">BUSINESS PERFORMANCE</span><h2>From records to decisions</h2><p>Impact figures are calculated from the business records stored in Karigar Link. They are not presented as guaranteed outcomes.</p></div><div class="impact-growth"><span>Recorded period change</span><strong>${growth}</strong></div></div>
 <div class="grid impact-kpis" style="margin-top:16px">${card('Products digitized',r.products_digitized,'Structured product identities')}${card('Historical revenue',money(r.revenue_recorded),'Recorded sales value')}${card('Transactions',r.historical_transactions,'Imported sales records')}${card('Units sold',r.units_recorded,'Recorded quantity')}${card('Markets reached',r.markets_reached,'Recorded cities / markets')}${card('Buyer profiles',r.buyer_profiles,'Available matching profiles')}${card('Average order value',money(r.avg_order_value),'Revenue ÷ transactions')}${card('Data quality',q,'Average imported dataset quality')}</div>
 <div class="impact-layout" style="margin-top:16px">
   <div class="card impact-wide"><div class="section-title"><div><h2>Revenue trend</h2><p class="sub">Recorded monthly revenue across the available history.</p></div><span class="pill">${months.length} periods</span></div>${svgLine()}</div>
   <div class="card"><div class="section-title"><div><h2>Top products</h2><p class="sub">Ranked by recorded revenue.</p></div></div>${bars(r.top_products||[],maxProd)}</div>
   <div class="card"><div class="section-title"><div><h2>Market reach</h2><p class="sub">Recorded revenue by city or market.</p></div></div>${bars(r.top_markets||[],maxMarket)}</div>
   <div class="card"><div class="section-title"><div><h2>Buyer / customer revenue</h2><p class="sub">Only names present in imported records are shown.</p></div></div>${bars(r.top_buyers||[],maxBuyer)}</div>
 </div>
 <div class="two" style="margin-top:16px">
   <div class="card"><div class="section-title"><h2>What the data says</h2><span class="pill">Decision support</span></div>${(r.recommendations||[]).map(x=>`<div class="insight-card"><span class="priority">${escapeHtml(x.priority)}</span><div><b>${escapeHtml(x.title)}</b><p>${escapeHtml(x.detail)}</p></div></div>`).join('')||'<div class="empty">Import historical data to unlock evidence-based recommendations.</div>'}</div>
   <div class="card"><div class="section-title"><h2>Impact measurement</h2><span class="pill">Recorded</span></div><div class="impact-framework"><div><b>Digitization</b><span>${r.products_digitized} product identities</span></div><div><b>Market access</b><span>${r.markets_reached} recorded markets</span></div><div><b>Business activity</b><span>${r.historical_transactions} historical transactions</span></div><div><b>Recorded value</b><span>${money(r.revenue_recorded)} revenue</span></div></div><div class="notice" style="margin-top:12px">${escapeHtml(r.note)}</div></div>
 </div>`;
}

function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function studio(){setHead('Market Ready Studio','One product in → market-ready catalogue, price, market and buyer action out.');content.innerHTML=`
<div class="studio-hero"><div><span class="eyebrow">FREE-FIRST PRODUCT ASSISTANT</span><h2>Make My Product Market Ready</h2><p>Upload a product photo, speak or type what you know, then generate a complete market-ready information pack without a paid AI API.</p></div><div class="studio-flow"><span>📷 Photo</span><b>→</b><span>🎙️ Voice/Text</span><b>→</b><span>✨ Intelligence</span><b>→</b><span>🛒 Market Action</span></div></div>
<div class="studio-grid"><div class="card"><div class="section-title"><h2>1. Product input</h2><span class="pill">Free</span></div><form id="studioForm" onsubmit="generateMarketReady(event)">
<label class="field"><span>Product name</span><input name="name" placeholder="e.g. Bamboo Storage Basket" required></label>
<div class="two"><label class="field"><span>Craft</span><input name="craft" placeholder="Bamboo Craft"></label><label class="field"><span>Material</span><input name="material" placeholder="Bamboo"></label></div>
<div class="two"><label class="field"><span>Region</span><input name="region" placeholder="Madhya Pradesh"></label><label class="field"><span>Technique</span><input name="technique" placeholder="Handwoven"></label></div>
<label class="field"><span>Product description</span><textarea name="description" rows="4" placeholder="Tell Karigar Link what the product is, how it is made, its use, size, story, etc."></textarea></label>
<label class="field"><span>Voice input</span><div class="voice-row"><textarea id="voiceText" name="voice_text" rows="3" placeholder="Press the microphone and speak naturally."></textarea><button type="button" class="btn voice-btn" onclick="startVoice()">🎙️ Speak</button></div><small id="voiceStatus" class="sub">Browser voice recognition works where Chrome supports it.</small></label>
<div class="two"><label class="field"><span>Current/list price ₹</span><input name="price" type="number" min="0" step="0.01" placeholder="499"></label><label class="field"><span>Estimated cost ₹</span><input name="cost" type="number" min="0" step="0.01" placeholder="330"></label></div>
<label class="field"><span>Weekly production capacity</span><input name="capacity" type="number" min="0" placeholder="20"></label>
<label class="field"><span>Product photo</span><input id="photoInput" name="photo" type="file" accept="image/*" onchange="previewPhoto(event)"><small class="sub">The photo is stored locally for the demo. The current free engine uses your text/voice to produce explainable product intelligence.</small></label>
<img id="photoPreview" class="photo-preview" hidden alt="Product preview">
<button class="btn primary full" type="submit">✨ Generate Market-Ready Pack</button></form></div>
<div id="studioResult"><div class="card empty">Your generated catalogue, pricing logic, market recommendation and buyer actions will appear here.</div></div></div>`}
function previewPhoto(e){const f=e.target.files?.[0],img=$('#photoPreview');if(!f)return;img.src=URL.createObjectURL(f);img.hidden=false}
function startVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){$('#voiceStatus').textContent='Voice recognition is not available in this browser. Try Chrome desktop.';return}const r=new SR();r.lang='hi-IN';r.interimResults=false;r.maxAlternatives=1;$('#voiceStatus').textContent='Listening… speak about the product.';r.onresult=e=>{$('#voiceText').value=(($('#voiceText').value+' '+e.results[0][0].transcript).trim());$('#voiceStatus').textContent='Voice captured. You can edit the text before generating.'};r.onerror=()=>$('#voiceStatus').textContent='Voice capture stopped. You can type instead.';r.onend=()=>{if($('#voiceStatus').textContent==='Listening… speak about the product.')$('#voiceStatus').textContent='Voice capture ended.'};r.start()}
async function generateMarketReady(e){e.preventDefault();const f=new FormData(e.target);const r=await fetch(API+'/api/market-ready',{method:'POST',body:f});if(!r.ok){$('#studioResult').innerHTML='<div class="notice error">Could not generate the market-ready pack.</div>';return}const x=await r.json();window.marketReady=x;const c=x.commercial,m=x.market,cat=x.catalogue,mar=x.marketing;$('#studioResult').innerHTML=`<div class="card"><div class="section-title"><h2>2. Market-ready result</h2><span class="pill">${x.confidence} confidence</span></div><div class="result-actions"><button class="btn primary" onclick="printMarketReady()">📄 Print / Save Catalogue PDF</button><button class="btn alt" onclick="copyText(window.marketReady.marketing.whatsapp)">📲 Copy WhatsApp</button></div><div class="studio-result-grid">
<div><span class="label">Product identity</span><h2>${escapeHtml(x.identity.product_name)}</h2><p class="sub">${escapeHtml(x.identity.craft)} · ${escapeHtml(x.identity.material)} · ${escapeHtml(x.identity.technique)} · ${escapeHtml(x.identity.region)}</p></div>
<div class="decision-box"><span class="label">Primary market</span><b>${escapeHtml(m.primary_market)}</b><small>Recommended from product/use signals</small></div>
</div>
${section('AI-assisted catalogue',`<div class="copy-block"><span class="label">Marketplace title</span><h2>${escapeHtml(cat.title)}</h2><span class="label">Short description</span><p>${escapeHtml(cat.short_description)}</p><span class="label">Detailed description</span><p>${escapeHtml(cat.long_description)}</p><span class="label">Craft story</span><p class="story">${escapeHtml(cat.story)}</p></div>`)}
${section('Smart pricing',`<div class="grid mini-grid">${card('Minimum sustainable',money(c.minimum_sustainable),'Cost floor + 15% protection')}${card('Recommended retail',money(c.recommended_retail),'Retail decision point')}${card('Recommended B2B',money(c.recommended_b2b),'Bulk-friendly decision point')}${card('Gross margin',c.gross_margin_percent+'%','At current price')}</div><div class="notice">Pricing is decision support. Validate final prices against real buyer quotes and market conditions.</div>`)}
${section('Where should I sell this?',`<div class="decision-box"><span class="label">Best market</span><h2>${escapeHtml(m.primary_market)}</h2><p>Suggested customer segments: ${m.customer_segments.map(escapeHtml).join(' · ')}</p></div><div class="channel-grid">${m.channels.map((z,i)=>`<div class="channel"><b>${i+1}</b><span>${escapeHtml(z)}</span></div>`).join('')}</div>`)}
${section('Ready-to-use marketing',`<div class="copy-tabs"><div><span class="label">WhatsApp</span><p class="copy-card">${escapeHtml(mar.whatsapp)}</p></div><div><span class="label">Instagram</span><p class="copy-card">${escapeHtml(mar.instagram)}</p></div><div><span class="label">B2B buyer pitch</span><p class="copy-card">${escapeHtml(mar.buyer_pitch)}</p></div></div>`)}
${section('Buyer action',`<p class="sub">Don't stop at a catalogue. Send an actual enquiry to the artisan record so the demo has a measurable market-linkage action.</p><button class="btn primary" onclick="openEnquiry(${Number(new FormData(e.target).get('product_id')||0)})">✉ Create Buyer Enquiry</button><div class="notice">${escapeHtml(x.note)}</div>`)}
${section('Hindi catalogue',`<p class="hindi" lang="hi">${escapeHtml('यह '+x.identity.product_name+' '+x.identity.region+' में '+x.identity.material+' से '+x.identity.technique+' द्वारा बनाया गया हस्तनिर्मित उत्पाद है। यह '+m.primary_market+' और उपहार के लिए उपयुक्त है।')}</p>`)}</div>`}
