async function enquiries(){setHead('Buyer Enquiries','Turn market matching into a real buyer connection and record the next business action.');state.products=await api('/api/products');const rows=await api('/api/enquiries');content.innerHTML=`<div class="grid studio-grid"><div class="card"><div class="section-title"><h2>New enquiry</h2><span class="pill">Market linkage action</span></div><form onsubmit="submitEnquiry(event)"><label class="field"><span>Product</span><select id="enqProduct" name="product_id">${state.products.map(p=>`<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('')}</select></label><div class="two"><label class="field"><span>Buyer name</span><input name="buyer_name" required placeholder="Buyer / shop / institution"></label><label class="field"><span>Buyer type</span><select name="buyer_type"><option>Retail</option><option>Corporate</option><option>Institutional</option><option>Tourist / Souvenir</option></select></label></div><div class="two"><label class="field"><span>City</span><input name="city" placeholder="Indore"></label><label class="field"><span>Quantity</span><input name="quantity" type="number" min="1" value="10"></label></div><label class="field"><span>Budget ₹</span><input name="budget" type="number" min="0" step="0.01" placeholder="5000"></label><label class="field"><span>Message</span><textarea name="message" rows="4" placeholder="Tell the artisan what you need."></textarea></label><button class="btn primary full">Send / Record Enquiry</button></form></div><div class="card"><div class="section-title"><h2>Recorded enquiries</h2><span class="pill">${rows.length}</span></div>${rows.length?rows.map(x=>`<div class="enquiry"><div><b>${escapeHtml(x.buyer_name)}</b><span>${escapeHtml(x.buyer_type)} · ${escapeHtml(x.city||'Location not specified')}</span></div><div><b>${escapeHtml(x.product||'Product')}</b><span>${x.quantity} units · ₹${Number(x.budget||0).toLocaleString('en-IN')}</span></div><em>${escapeHtml(x.status)}</em></div>`).join(''):'<div class="empty">No buyer enquiries yet.</div>'}</div></div>`}
