async function loadV2Products(){
  const ps=await api('/api/products');
  state.products=ps;
  return ps;
}
function productSelector(products,selected,onchange){
  return `<div class="product-context"><div><span class="eyebrow">PRODUCT CONTEXT</span><h2>Select one product</h2><p>All intelligence below is calculated for the product you choose.</p></div><select class="product-picker" onchange="${onchange}(this.value)"><option value="">Choose a product...</option>${products.map(p=>`<option value="${p.id}" ${String(p.id)===String(selected||'')?'selected':''}>${escapeHtml(p.name)} · ${escapeHtml(p.craft||'Craft')}</option>`).join('')}</select></div>`;
}
async function forecastPage(productId=''){
 setHead('Demand & Forecasting','PRODUCTION PLANNING · What should I make, when, and how much?');
 const ps=await loadV2Products();
 if(!productId){content.innerHTML=productSelector(ps,'','forecastPage')+`<div class="card empty-v2"><div class="empty-icon">📈</div><h2>Start with one product</h2><p>This is a production planning tool, not a market dashboard. Select a product to analyse its own sales history, trend, seasonality and capacity.</p><div class="notice">Example: if a basket has been selling 35–45 units/month and capacity is 20/week, the tool converts that history into a three-month preparation plan.</div></div>`;return}
 const x=await api('/api/forecast?product_id='+productId), p=x.selected; if(!p){content.innerHTML=productSelector(ps,productId,'forecastPage')+'<div class="notice error">Product not found.</div>';return}
 const hist=(p.historical_months_detail||[]).map(h=>`<div class="forecast-row"><b>${escapeHtml(h.month)}</b><span>${h.units} units</span><span>${money(h.revenue)}</span></div>`).join('');
 const plan=(p.forecast||[]).map(f=>`<div class="forecast-row"><b>${escapeHtml(f.month)}</b><span>${f.expected_units} units</span><span>${money(f.expected_revenue)}</span><em>capacity gap ${f.capacity_gap}</em></div>`).join('');
 const status=p.recommended_additional_production>0?`<div class="notice warning"><b>Capacity pressure:</b> the next 3-month forecast is about ${p.recommended_additional_production} units above estimated monthly capacity. Consider pre-production, supplier planning or a realistic delivery date.</div>`:`<div class="notice success"><b>Capacity looks sufficient:</b> no immediate production gap is detected against the forecast baseline.</div>`;
 content.innerHTML=productSelector(ps,productId,'forecastPage')+`<div class="v2-hero"><div><span class="eyebrow">PRODUCTION PLAN</span><h2>${escapeHtml(p.product.name)}</h2><p>${escapeHtml(p.product.craft||'Craft')} · ${escapeHtml(p.product.region||'India')} · based on ${p.history_transactions} recorded transactions</p></div><span class="confidence ${String(p.confidence).toLowerCase()}">${escapeHtml(p.confidence)} confidence</span></div>
 <div class="grid mini-grid">${card('Recent run-rate',p.baseline_monthly_units+' units/month','Last 3 recorded months')}${card('Trend',escapeHtml(p.trend_direction),`${p.trend_percent>=0?'+':''}${p.trend_percent}% vs earlier history`)}${card('Next 3 months',p.expected_units_next_3_months+' units','Expected product demand')}${card('Capacity',p.capacity_monthly_estimate+' units/month','Weekly capacity × 4.33')}</div>
 <div class="grid two-col"><div class="card"><div class="section-title"><h2>What actually happened?</h2><span class="pill">Historical evidence</span></div><p class="muted">Use this section to understand the product before trusting the forecast.</p>${hist||'<div class="empty-inline">No product history found.</div>'}<div class="decision-box"><span class="label">Average realized price</span><b>${money(p.average_realized_price)}</b><small>Recorded selling price, not just list price</small></div></div>
 <div class="card"><div class="section-title"><h2>What is likely next?</h2><span class="pill">3-month planning</span></div>${plan}<div class="decision-box"><span class="label">Peak forecast month</span><b>${escapeHtml(p.peak_forecast?.month||'—')}</b><small>${p.peak_forecast?.expected_units||0} units expected</small></div></div></div>
 <div class="card"><div class="section-title"><h2>Production decision</h2><span class="pill">Action</span></div>${status}<div class="market-actions"><div><b>${escapeHtml(p.decision)}</b><span>Translate the forecast into a production commitment only after checking capacity and incoming enquiries.</span></div><div><b>Prepare inputs</b><span>Plan bamboo/material, labour time, packaging and dispatch capacity before the peak month.</span></div><div><b>Protect custom orders</b><span>Keep a buffer instead of allocating every expected unit to routine stock.</span></div></div></div>
 <div class="notice">Forecasting is intentionally separate from Market Intelligence: this page decides <b>how much to prepare</b>, not where to sell it.</div>`;
}
async function marketplace(productId=''){
 setHead('Digital Marketplace','BUYER ACTION · Turn one product into a buyer-facing opportunity and record the next step.');
 const ps=await loadV2Products();
 if(!productId){content.innerHTML=productSelector(ps,'','marketplace')+`<div class="card empty-v2"><div class="empty-icon">🛍️</div><h2>Start with one product</h2><p>This is the action layer. Select a product to see its listing, buyer requirements, feasibility and enquiry workflow.</p></div>`;return}
 const x=await api('/api/marketplace?product_id='+productId),p=x.selected;if(!p){content.innerHTML=productSelector(ps,productId,'marketplace')+'<div class="notice error">Product not found.</div>';return}
 const matches=x.matches||[];const strong=matches.filter(r=>r.match_score>=70);
 const matchHtml=matches.slice(0,6).map(r=>`<div class="buyer-opportunity"><div><span class="eyebrow">${escapeHtml(r.buyer_type)}</span><h3>${escapeHtml(r.buyer_name)}</h3><p>${escapeHtml(r.city||'Location not specified')} · ${r.quantity} units · ${money(r.budget_min)}–${money(r.budget_max)} / unit · ${r.delivery_days} days</p><strong>${r.match_score}/100 match</strong><ul>${r.match_reasons.map(z=>`<li>${escapeHtml(z)}</li>`).join('')}</ul></div><button class="btn primary" onclick="openEnquiry(${p.id})">Create enquiry</button></div>`).join('')||'<div class="empty-inline">No open buyer requirements yet. Post one below to create demand.</div>';
 content.innerHTML=productSelector(ps,productId,'marketplace')+`<div class="marketplace-product"><div class="marketplace-product-main"><div class="product-image-placeholder large">◇</div><div><span class="eyebrow">BUYER-FACING LISTING</span><h2>${escapeHtml(p.name)}</h2><p>${escapeHtml(p.description||'Handmade artisan product')}</p><div class="tag-row"><span class="tag">${escapeHtml(p.craft||'Craft')}</span><span class="tag">${escapeHtml(p.material||'Material')}</span><span class="tag">${escapeHtml(p.region||'India')}</span></div></div></div><div class="marketplace-offer"><span>Indicative price</span><b>${money(p.price)}</b><small>${p.capacity_week} units/week estimated capacity</small><button class="btn primary" onclick="openEnquiry(${p.id})">Create Buyer Enquiry</button></div></div>
 <div class="grid mini-grid">${card('Strong buyer matches',strong.length,'Requirements scoring 70+')}${card('Open requirements',matches.length,'Available in local marketplace')}${card('Monthly capacity',Math.round(p.capacity_week*4.33)+' units','Used for bulk feasibility')}${card('Listing readiness','Ready','Product can be presented to buyers')}</div>
 <div class="card"><div class="section-title"><h2>Buyer opportunities</h2><span class="pill">Who can buy this?</span></div>${matchHtml}</div>
 <div class="card"><div class="section-title"><h2>Listing preview</h2><span class="pill">Copy-ready</span></div><h3>${escapeHtml(p.listing_title)}</h3><p>${escapeHtml(p.buyer_pitch)}</p><div class="actions"><button class="btn primary" onclick="openEnquiry(${p.id})">Send an enquiry</button><button class="btn alt" onclick="navigator.clipboard?.writeText(${JSON.stringify(p.buyer_pitch)})">Copy buyer pitch</button></div></div>
 <div class="card"><div class="section-title"><h2>Create buyer demand</h2><span class="pill">Buyer request board</span></div><form onsubmit="postBuyerRequest(event)"><div class="two"><label class="field"><span>Buyer / organisation</span><input name="buyer_name" required></label><label class="field"><span>Buyer type</span><select name="buyer_type"><option>Retail</option><option>Corporate</option><option>Institutional</option></select></label></div><div class="two"><label class="field"><span>City</span><input name="city"></label><label class="field"><span>Product need</span><input name="product_need" required value="${escapeHtml(p.name)}"></label></div><div class="two"><label class="field"><span>Quantity</span><input name="quantity" type="number" value="50" min="1"></label><label class="field"><span>Delivery days</span><input name="delivery_days" type="number" value="30" min="1"></label></div><div class="two"><label class="field"><span>Budget min ₹</span><input name="budget_min" type="number" value="${Math.round(p.price*.8)||200}"></label><label class="field"><span>Budget max ₹</span><input name="budget_max" type="number" value="${Math.round(p.price*1.1)||500}"></label></div><label class="field"><span>Notes</span><textarea name="notes" rows="3" placeholder="Delivery, customization, packaging or repeat-order details"></textarea></label><button class="btn primary">Publish Requirement</button></form></div>
 <div class="notice">Marketplace is intentionally different from Market Intelligence: this page is about <b>buyer interaction and recorded action</b>. It is a local prototype workflow, not a claimed live connection to GeM or Indiahandmade.</div>`;
}
