let searchTimer=null;
function closeSearch(){const box=$('#searchResults');if(box)box.hidden=true}
async function globalSearch(){
 const input=$('#globalSearch'),box=$('#searchResults');if(!input||!box)return;
 const q=input.value.trim().toLowerCase();
 if(!q){box.innerHTML='<div class="search-empty">Type a product, market, scheme, opportunity, or section name.</div>';box.hidden=false;return}
 box.innerHTML='<div class="search-empty">Searching Karigar Link…</div>';box.hidden=false;
 try{
  const settled=await Promise.allSettled(['/api/products','/api/market-news','/api/government-schemes','/api/business-opportunities','/api/marketplace'].map(url=>api(url)));
  const get=i=>settled[i].status==='fulfilled'?settled[i].value:null;
  const products=get(0),news=get(1),schemes=get(2),opps=get(3),marketplace=get(4),rows=[];
  const matches=vals=>vals.filter(v=>v!==null&&v!==undefined).map(v=>Array.isArray(v)?v.join(' '):v).join(' ').toLowerCase().includes(q);
  const add=(type,title,meta,page)=>rows.push({type,title:String(title||''),meta:String(meta||''),page});
  (Array.isArray(products)?products:(products?.products||[])).forEach(x=>{if(matches([x.name,x.craft,x.material,x.region,x.description]))add('Product',x.name,[x.craft,x.region].filter(Boolean).join(' · '),'products')});
  (Array.isArray(marketplace)?marketplace:(marketplace?.products||[])).forEach(x=>{if(matches([x.name,x.category,x.craft,x.region,x.description]))add('Marketplace',x.name,[x.category,x.region].filter(Boolean).join(' · '),'marketplace')});
  (news?.items||[]).forEach(x=>{if(matches([x.title,x.category,x.detail,x.source]))add('Market News',x.title,x.date||x.category||'','news')});
  (schemes?.items||[]).forEach(x=>{if(matches([x.name,x.category,x.support_type,x.target,x.tags,x.eligibility,x.support,x.summary,x.detail]))add('Government Scheme',x.name,x.support_type||x.category||'Official support','schemes')});
  (opps?.items||[]).forEach(x=>{if(matches([x.title,x.type,x.location,x.detail,x.eligibility,x.why]))add('Business Opportunity',x.title,[x.location,x.start_date].filter(Boolean).join(' · '),'opportunities')});
  const sections=[['Overview','Dashboard and business summary','home'],['Products','Product catalogue and product management','products'],['Digital Marketplace','Marketplace and buyer matching','marketplace'],['Buyer Enquiries','Buyer messages and enquiries','enquiries'],['Plans & Store Sync','Subscription plans','subscriptions'],['Customer Orders','Order management','sellerorders'],['Demand & Forecasting','Forecast sales demand','forecast'],['Pricing Intelligence','Pricing and margins','pricing'],['Market Intelligence','Markets and buyer matching','markets'],['Smart Catalogue','Catalogue content','catalogue'],['Market Ready Studio','Create market-ready listings','studio'],['Historical Sales Data','Imported CSV history and records','history'],['Business Insights & Impact','Business analytics and impact charts','impact'],['Market News','Market news and updates','news'],['Government Schemes','Government support schemes','schemes'],['Business Opportunities','Events, fairs and selling opportunities','opportunities']];
  sections.forEach(([title,meta,page])=>{if(matches([title,meta]))add('Website section',title,meta,page)});
  const unique=rows.filter((x,i,a)=>x.title&&a.findIndex(y=>y.type===x.type&&y.title===x.title)===i).slice(0,12);
  if(!unique.length){const failed=settled.some(x=>x.status==='rejected');box.innerHTML=`<div class="search-empty">${failed?'Some live data sources could not be reached. ':''}No matching result found. Try a product name, craft, market, scheme, event, or section name.</div>`;return}
  box.innerHTML=unique.map(x=>`<button class="search-result" type="button" onclick="openSearchResult('${x.page}')"><span class="search-type">${escapeHtml(x.type)}</span><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(x.meta)}</small></button>`).join('');
 }catch(e){box.innerHTML=`<div class="search-empty error-text">Search could not load results. ${escapeHtml(e.message)}</div>`}
}
function openSearchResult(page){closeSearch();const input=$('#globalSearch');if(input)input.blur();const nav=document.querySelector(`.nav[data-page="${page}"]`);if(nav){nav.click()}else{boot(page)}}
function initGlobalSearch(){const input=$('#globalSearch');if(!input)return;input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();globalSearch()}if(e.key==='Escape')closeSearch()});input.addEventListener('input',()=>{clearTimeout(searchTimer);if(input.value.trim())searchTimer=setTimeout(globalSearch,250);else closeSearch()});document.addEventListener('click',e=>{if(!e.target.closest('.search-shell'))closeSearch()})}


