function applyLanguage(code){localStorage.setItem('karigar_language',code);document.documentElement.lang=code;const combo=document.querySelector('.goog-te-combo');if(combo&&code!=='en'){combo.value=code;combo.dispatchEvent(new Event('change'));}else if(combo&&code==='en'){combo.value='en';combo.dispatchEvent(new Event('change'));} const map=UI_TRANSLATIONS[code]||{};document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(map[k])el.textContent=map[k];});}
function refreshFullPageTranslation(){const code=localStorage.getItem('karigar_language')||'en';if(code==='en')return;const combo=document.querySelector('.goog-te-combo');if(combo){combo.value=code;combo.dispatchEvent(new Event('change'));}}
function initLanguage(){const sel=$('#languageSelect');if(!sel)return;const saved=localStorage.getItem('karigar_language')||'en';sel.value=saved;sel.onchange=()=>{applyLanguage(sel.value);setTimeout(refreshFullPageTranslation,250);};setTimeout(()=>applyLanguage(saved),1200);setTimeout(refreshFullPageTranslation,1800);}
function token(){return localStorage.getItem('karigar_token')||''}
async function authFetch(url,opt={}){opt.headers={...(opt.headers||{}),...(token()?{'Authorization':'Bearer '+token()}: {})};return api(url,opt)}
function openAuth(){if(document.getElementById('authModal'))return;document.body.insertAdjacentHTML('beforeend',`<div id="authModal" class="modal-backdrop"><div class="auth-modal"><button class="modal-close" onclick="closeAuth()">×</button><div class="eyebrow">KARIGAR LINK ACCOUNT</div><h2>Welcome to Karigar Link</h2><p class="sub">Sign in to manage your artisan business. You can also browse products and the storefront without signing in.</p><div class="auth-tabs"><button class="btn primary" id="loginTab" onclick="authMode('login')">Sign in</button><button class="btn alt" onclick="authMode('register')">Create account</button></div><div id="authBody"></div><button type="button" class="btn alt" style="width:100%;margin-top:12px" onclick="closeAuth()">Continue browsing without signing in</button></div></div>`);authMode('login');}
function closeAuth(){document.getElementById('authModal')?.remove()}
function authMode(mode){const b=$('#authBody');if(!b)return;b.innerHTML=mode==='login'?`<form onsubmit="submitLogin(event)"><div class="field"><label>Email or mobile</label><input id="authId" required placeholder="you@example.com or +919876543210"></div><div class="field"><label>Password</label><input id="authPass" type="password" required></div><button class="btn primary" style="margin-top:14px">Sign in</button><div class="auth-or">Mobile OTP is optional and can be used below.</div><div class="form"><div class="field"><label>Mobile</label><input id="otpPhone" placeholder="+919876543210"></div><div class="field"><label>OTP</label><input id="otpCode" placeholder="6 digits"></div></div><div class="actions"><button type="button" class="btn alt" onclick="sendOtp()">Send SMS OTP</button><button type="button" class="btn alt" onclick="verifyOtp()">Verify & Sign in</button></div></form>`:`<form onsubmit="submitRegister(event)"><div class="form"><div class="field"><label>Name</label><input id="regName" required></div><div class="field"><label>Email (optional)</label><input id="regEmail" type="email"></div><div class="field"><label>Password</label><input id="regPass" type="password" minlength="6" required></div><div class="field"><label>Mobile (optional)</label><input id="regPhone" placeholder="+919876543210"></div></div><button class="btn primary" style="margin-top:14px">Create account</button><p class="sub">You can create an account without a mobile number. SMS OTP is an optional sign-in method.</p></form>`}
async function submitLogin(e){e.preventDefault();try{const id=$('#authId').value.trim();const r=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:id.includes('@')?id:'',phone:id.includes('@')?'':id,password:$('#authPass').value})});localStorage.setItem('karigar_token',r.token);localStorage.setItem('karigar_user',JSON.stringify(r.user));closeAuth();updateProfile();}catch(e){alert(e.message)}}
async function submitRegister(e){e.preventDefault();try{const r=await api('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#regName').value,email:$('#regEmail').value,password:$('#regPass').value,phone:$('#regPhone').value,language:$('#languageSelect')?.value||'en'})});localStorage.setItem('karigar_token',r.token);localStorage.setItem('karigar_user',JSON.stringify(r.user));closeAuth();updateProfile();}catch(e){alert(e.message)}}
async function sendOtp(){const phone=$('#otpPhone')?.value.trim();if(!phone)return alert('Enter mobile number in international format.');try{await api('/api/auth/request-phone-otp',{method:'POST',body:new URLSearchParams({phone})});alert('SMS OTP sent.');}catch(e){alert(e.message)}}
async function verifyOtp(){const phone=$('#otpPhone')?.value.trim(),code=$('#otpCode')?.value.trim();if(!phone||!code)return alert('Enter mobile and OTP.');try{const r=await api('/api/auth/verify-phone-otp',{method:'POST',body:new URLSearchParams({phone,code,name:'',password:'ChangeMe123',language:$('#languageSelect')?.value||'en'})});localStorage.setItem('karigar_token',r.token);localStorage.setItem('karigar_user',JSON.stringify(r.user));closeAuth();updateProfile();}catch(e){alert(e.message)}}
function updateProfile(){const b=$('#profileBtn'),u=JSON.parse(localStorage.getItem('karigar_user')||'null');if(b)b.textContent=u?(u.name||'Account'):'Sign in'}
function logout(){const t=token();if(t)fetch('/api/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+t}}).catch(()=>{});localStorage.removeItem('karigar_token');localStorage.removeItem('karigar_user');updateProfile()}
function ensureAssistant(){
  if(document.getElementById('aiAssistant')) return;
  document.body.insertAdjacentHTML('beforeend',`<button type="button" id="aiAssistantFab" class="ai-fab" onclick="toggleAssistant()">✦ Assistant</button><section id="aiAssistant" class="ai-panel" hidden aria-label="Karigar AI Assistant"><div class="ai-head"><div><b>Karigar Assistant</b><small id="aiStatus">Ready · remembers this conversation</small></div><div class="ai-head-actions"><button type="button" class="ai-clear" onclick="clearAssistantHistory()" title="Clear conversation">Clear</button><button type="button" class="ai-close" aria-label="Close assistant" onclick="closeAssistant()">×</button></div></div><div id="aiMessages" class="ai-messages"></div><div id="aiSuggestions" class="ai-suggestions"><button type="button" onclick="assistantQuick('Help me understand my business data')">Help me</button><button type="button" onclick="assistantQuick('Build a catalogue for my product')">Build catalogue</button><button type="button" onclick="assistantQuick('Show my pricing intelligence')">Pricing</button></div><form class="ai-compose" onsubmit="sendAssistant(event)"><input id="aiInput" placeholder="Ask Karigar Link anything…" autocomplete="off"><button id="aiSend">Send</button></form></section>`);
  renderAssistantHistory();
}
function assistantHistory(){try{return JSON.parse(localStorage.getItem('karigar_ai_history')||'[]')}catch{return []}}
function saveAssistantHistory(h){localStorage.setItem('karigar_ai_history',JSON.stringify(h.slice(-40)))}
function clearAssistantHistory(){localStorage.removeItem('karigar_ai_history');renderAssistantHistory();}
function renderAssistantHistory(){const box=$('#aiMessages');if(!box)return;const h=assistantHistory();box.innerHTML=h.length?h.map(x=>`<div class="ai-msg ${x.role}">${escapeHtml(x.content)}</div>`).join(''):'<div class="ai-welcome"><b>Hi, I’m Karigar Assistant.</b><br><br>I can answer questions about your Karigar Link data and operate the app for you. You can say things like:<br>• “Build a catalogue for my bamboo basket.”<br>• “What is my current price and margin?”<br>• “Forecast demand for this product.”<br>• “Show me the best buyer matches.”<br>• “Open historical sales.”<br><br>I’ll remember the recent conversation on this device.</div>';box.scrollTop=box.scrollHeight}
function assistantQuick(msg){const i=$('#aiInput');if(i){i.value=msg;i.focus();}}
function closeAssistant(){const p=$('#aiAssistant');if(p){p.hidden=true;document.body.classList.remove('assistant-open')}}
async function checkAssistantModelStatus(){const s=$('#aiStatus');if(!s)return;try{const r=await api('/api/assistant/status');if(r.status==='connected')s.textContent=`Local AI connected · ${r.model}`;else if(r.status==='model_missing')s.textContent=`Ollama running · install ${r.model}`;else s.textContent='Ollama offline · start Ollama to chat';}catch{s.textContent='Local AI status unavailable';}}
function toggleAssistant(){ensureAssistant();const p=$('#aiAssistant');p.hidden=!p.hidden;document.body.classList.toggle('assistant-open',!p.hidden);if(!p.hidden){renderAssistantHistory();checkAssistantModelStatus();setTimeout(()=>$('#aiInput')?.focus(),0)}}
async function sendAssistant(e){
  e.preventDefault();
  ensureAssistant();
  const input=$('#aiInput'), send=$('#aiSend'), status=$('#aiStatus');
  const msg=input.value.trim(); if(!msg)return;
  input.value=''; input.disabled=true; if(send)send.disabled=true; if(status)status.textContent='Thinking…';
  let h=assistantHistory();
  h.push({role:'user',content:msg}); saveAssistantHistory(h); renderAssistantHistory();
  const box=$('#aiMessages');
  if(box){const typing=document.createElement('div');typing.className='ai-msg assistant ai-typing';typing.textContent='Thinking…';typing.id='aiTyping';box.appendChild(typing);box.scrollTop=box.scrollHeight}
  try{
    const current=document.querySelector('.nav.active')?.dataset.page||'home';
    const r=await api('/api/assistant',{method:'POST',body:new URLSearchParams({message:msg,history:JSON.stringify(h.slice(-40)),context:JSON.stringify({page:current,language:localStorage.getItem('karigar_language')||'en',products:state.products||[]})})});
    $('#aiTyping')?.remove();
    h=assistantHistory(); h.push({role:'assistant',content:r.reply||'Done.'}); saveAssistantHistory(h); renderAssistantHistory();
    if(status)status.textContent=r.mode==='llm'?`Local AI connected · ${r.model||'Ollama'}`:r.mode==='offline'?'Ollama offline · start Ollama and retry':'Karigar Link · ready';
    if(r.action && r.action.type && r.action.type!=='none'){
      await executeAssistantAction(r.action);
    }
  }catch(err){
    $('#aiTyping')?.remove();
    h=assistantHistory(); h.push({role:'assistant',content:'I could not complete that request. '+(err.message||'Please try again.')}); saveAssistantHistory(h); renderAssistantHistory(); if(status)status.textContent='Ready';
  }finally{input.disabled=false;if(send)send.disabled=false;input.focus();}
}
async function executeAssistantAction(action){
  if(!action)return;
  if(action.type==='navigate'){
    const page=action.page||'home';
    const nav=document.querySelector(`.nav[data-page="${page}"]`);
    if(nav){document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));nav.classList.add('active');}
    await boot(page, action.product_id||'', action);
    return;
  }
  if(action.type==='open_product'){
    const nav=document.querySelector('.nav[data-page="products"]');
    if(nav)nav.click();
    return;
  }
}
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeAuth();closeAssistant();closeSearch()}});

