async function sellerOrdersPage(){setHead('Customer Orders','Review orders containing your products and follow fulfilment progress.');const r=await api('/api/seller/orders?artisan_id=1');const orders=r.orders||[];content.innerHTML=`<div class="notice"><b>Order management</b><br>These are local demo orders. Keep customer information private. Payment collection, shipping labels and automated customer notifications are not connected.</div><div class="card"><div class="section-title"><h2>Orders for your products</h2><span class="pill">${orders.length} orders</span></div>${orders.length?`<div style="overflow:auto"><table class="table"><tr><th>Order</th><th>Customer / delivery</th><th>Items</th><th>Seller items value</th><th>Payment</th><th>Status</th></tr>${orders.map(o=>`<tr><td><b>${escapeHtml(o.order_number)}</b><br><span class="sub">${new Date(o.created_at).toLocaleString()}</span></td><td>${escapeHtml(o.customer_name)}<br>${escapeHtml(o.phone)}<br>${escapeHtml(o.city)} ${escapeHtml(o.pincode)}<br><span class="sub">${escapeHtml(o.address)}</span></td><td>${o.items.map(i=>`${escapeHtml(i.product_name)} × ${i.quantity}`).join('<br>')}</td><td>${money(o.seller_subtotal)}</td><td>${escapeHtml(o.payment_method)}<br><span class="sub">${escapeHtml(o.payment_status)}</span></td><td><span class="pill">${escapeHtml(o.order_status)}</span></td></tr>`).join('')}</table></div>`:'<div class="empty">No customer orders yet. Activate the ₹199 plan, publish a product, then place a test order from Customer Storefront.</div>'}</div>`}

async function subscriptionsPage(){
 setHead('Plans & Store Sync','Choose an artisan plan and manage what is published to the customer storefront.');
 const [r,ps]=await Promise.all([api('/api/subscriptions/status?artisan_id=1'),api('/api/products?artisan_id=1')]); state.products=ps;
 const sub=r.subscription, active=r.plan;
 content.innerHTML=`<div class="notice"><b>Two simple plans. No marketplace sales commission in this product model.</b><br><span class="sub">This build uses demo activation only. It does not collect real subscription payments. Connect a verified payment gateway before launch.</span></div>
 <div class="grid" style="margin-top:16px">${r.plans.map(p=>`<div class="card plan-card"><div class="section-title"><h2>${escapeHtml(p.name)}</h2>${active?.code===p.code?'<span class="pill">Current plan</span>':''}</div><div class="metric">₹${p.price}<span style="font-size:13px;font-weight:600"> / 30 days</span></div><ul class="clean-list">${p.features.map(f=>`<li>${escapeHtml(f)}</li>`).join('')}</ul><div class="sub" style="margin:12px 0">${p.marketplace_selling?'Includes customer marketplace selling.':'Does not include public product listings.'}</div><button class="btn ${active?.code===p.code?'alt':'primary'}" onclick="activatePlan('${p.code}')">${active?.code===p.code?'Renew / switch plan':'Activate demo plan'}</button></div>`).join('')}</div>
 <div class="card" style="margin-top:16px"><div class="section-title"><h2>Subscription status</h2><span class="pill">${sub?escapeHtml(sub.status):'No active plan'}</span></div>${sub?`<p><b>${escapeHtml(active?.name||sub.plan_code)}</b> · Expires ${new Date(sub.expires_at).toLocaleDateString()} · Reference ${escapeHtml(sub.payment_reference||'—')}</p>`:'<p>No active plan. Choose a plan above to unlock its features.'}<div class="sub">Marketplace publishing is only enabled while the ₹199 plan is active and the product has a valid price and available stock.</div></div>
 <div class="card" style="margin-top:16px"><div class="section-title"><h2>Product publishing & inventory</h2><span class="pill">${ps.length} products</span></div><p class="sub">Set stock above zero, then publish. A successful publish saves the listing to the shared database so it can appear on the separate customer storefront.</p><div id="listingFeedback" class="listing-feedback" role="status" aria-live="polite"></div>${ps.map(p=>`<div class="listing-editor"><div><b>${escapeHtml(p.name)}</b><div class="sub">${escapeHtml(p.craft||'Craft')} · ${money(p.price)} · Current status: <span id="listingStatus_${p.id}">${escapeHtml(p.marketplace_status||'draft')}</span></div></div><div class="listing-fields"><label>Stock<input type="number" min="0" max="100000" id="stock_${p.id}" value="${Number(p.stock||0)}"></label><label>SKU<input id="sku_${p.id}" value="${escapeHtml(p.sku||'')}" placeholder="Optional SKU"></label><label>Image URL<input id="img_${p.id}" value="${escapeHtml(p.image_url||'')}" placeholder="https://…"></label></div><div class="actions"><button type="button" class="btn primary" data-listing-action="publish" data-product-id="${p.id}">Publish / Sync</button><button type="button" class="btn alt" data-listing-action="unpublish" data-product-id="${p.id}">Unpublish</button></div></div>`).join('')||'<div class="empty">Add products in the Products section first.</div>'}</div>`;
}
async function activatePlan(code){if(!confirm('Activate this plan in DEMO mode? No payment will be collected.'))return;try{const r=await api('/api/subscriptions/activate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({artisan_id:1,plan_code:code,payment_mode:'demo'})});alert(r.notice);subscriptionsPage()}catch(e){alert(e.message)}}
async function saveListing(id,publish){const feedback=$('#listingFeedback');const buttons=[...document.querySelectorAll(`[data-product-id="${id}"][data-listing-action]`)];const status=$('#listingStatus_'+id);const stock=Number($('#stock_'+id)?.value||0);if(publish&&stock<=0){if(feedback){feedback.className='listing-feedback error';feedback.textContent='Set stock to at least 1 before publishing this product.'}return}if(feedback){feedback.className='listing-feedback';feedback.textContent=publish?'Publishing product and syncing inventory…':'Unpublishing product…'}buttons.forEach(b=>b.disabled=true);try{const r=await api('/api/products/'+id+'/marketplace-listing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({artisan_id:1,stock,sku:$('#sku_'+id)?.value||'',image_url:$('#img_'+id)?.value||'',publish})});if(status)status.textContent=r.status||r.product?.marketplace_status||(publish?'published':'draft');if(feedback){feedback.className='listing-feedback success';feedback.textContent=publish?`Published successfully. Product #${id} is saved to the shared catalogue. Open the Customer Storefront and refresh to verify it.`:`Product #${id} was unpublished and removed from the storefront.`}if(publish){const sub=await api('/api/subscriptions/status?artisan_id=1');if(!sub.marketplace_selling&&feedback){feedback.className='listing-feedback error';feedback.textContent='The listing was saved, but the ₹199 Marketplace plan is not active, so customers will not see it.'}}}catch(e){if(feedback){feedback.className='listing-feedback error';feedback.textContent=e.message||'Could not publish this product. Check your plan, stock and price, then try again.'}}finally{buttons.forEach(b=>b.disabled=false)}}
function initListingActions(){if(!content||content.dataset.listingActionsBound==='1')return;content.dataset.listingActionsBound='1';content.addEventListener('click',e=>{const btn=e.target.closest('[data-listing-action][data-product-id]');if(!btn)return;e.preventDefault();const id=Number(btn.dataset.productId);saveListing(id,btn.dataset.listingAction==='publish')})}

function initNavigation(){document.querySelectorAll('.nav').forEach(b=>{if(b.tagName!=='BUTTON')return;b.addEventListener('click',()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');boot(b.dataset.page);});});}

async function boot(page='home',productId='',assistantAction=null){try{if(page==='home')await home();if(page==='history')await history();if(page==='products')await products();if(page==='pricing')await pricing();if(page==='markets')await markets(productId);if(page==='forecast')await forecastPage(productId);if(page==='marketplace')await marketplace();if(page==='subscriptions')await subscriptionsPage();if(page==='sellerorders')await sellerOrdersPage();if(page==='news')await news();if(page==='schemes')await schemes();if(page==='opportunities')await opportunities();if(page==='studio')await studio();if(page==='enquiries')await enquiries();if(page==='catalogue')await catalogue(productId);if(page==='impact')await impact()}catch(e){content.innerHTML='<div class="notice error"><b>Unable to load this page</b><br>'+escapeHtml(e.message)+'</div>'}}
ensureAssistant();initLanguage();updateProfile();initNavigation();initGlobalSearch();initListingActions();boot('home');
if(!token())setTimeout(openAuth,350);
